function cfg(){return {myCall:$('myCall').value.toUpperCase().trim(),myDok:$('myDok').value.toUpperCase().trim(),duration:+$('duration').value,cqWpm:+$('cqWpm').value,minWpm:+$('minWpm').value,maxWpm:+$('maxWpm').value,boost599:Math.max(1,Math.min(20,+$('boost599').value||5)),pileup:Math.max(1,Math.min(10,Number.parseInt($('pileup').value,10)||1)),tone:+$('tone').value,noise:+$('noise').value,qrn:+$('qrn').value,pitch:+$('pitch').value,responseMin:+$('responseMin').value,responseMax:+$('responseMax').value,cut:$('cutStyle').value!=='off',cutStyle:$('cutStyle').value,cutDokNumbers:$('cutDokNumbers')?.checked||false,qsb:+$('qsbLevel').value,qrm:+$('qrmLevel').value,band:$('band').value,activity:$('activity').value,language:$('language')?.value||'en',debug:$('debugMode')?.checked||false,f74Mode:$('f74Mode')?.checked||false,germanOnly:$('germanOnly')?.checked||false,dxOnly:$('dxOnly')?.checked||false,dxRatio:+$('dxRatio')?.value||45};}
function initAudio(){if(!ac){ac=new AudioContext();master=ac.createGain();master.gain.value=.25;master.connect(ac.destination);makeNoise()}ac.resume();if(noiseNode?.g){const now=ac.currentTime;noiseNode.g.gain.cancelScheduledValues(now);noiseNode.g.gain.setValueAtTime(noiseNode.g.gain.value,now);noiseNode.g.gain.linearRampToValueAtTime(cfg().noise/500,now+.35)}}
