function updateBandAudio(){if(noiseNode?.g&&ac){const now=ac.currentTime;noiseNode.g.gain.cancelScheduledValues(now);noiseNode.g.gain.setTargetAtTime(active?cfg().noise/500:0,now,.08)}}
function cutMap(){return cfg().cutStyle==='tn'?{'0':'T','9':'N'}:cfg().cutStyle==='ae'?{'1':'A','5':'E','9':'N','0':'T'}:{'1':'A','2':'U','3':'V','5':'E','7':'B','8':'D','9':'N','0':'T'}}
