function play(text,wpm=25,opt={}){initAudio();lastPhrase=text;const content=String(text).toUpperCase(),boost=Math.max(1,Math.min(20,+cfg().boost599||5)),boosted=new Set();for(let pos=content.indexOf('5NN');pos>=0;pos=content.indexOf('5NN',pos+3))for(let j=pos;j<pos+3;j++)boosted.add(j);const start=ac.currentTime+.06,pitch=opt.pitch||cfg().tone+(Math.random()-.5)*cfg().pitch,qsbStrength=Math.max(0,Math.min(100,+cfg().qsb||0)),qsbPeriod=2.2+Math.random()*2.4,qsbPhase=Math.random()*Math.PI*2,qsbFloor=qsbStrength<=50?1-(qsbStrength/50)*.58:.42-((qsbStrength-50)/50)*.34;let t=start;for(let ci=0;ci<content.length;ci++){const ch=content[ci],dot=1.2/(boosted.has(ci)?Math.min(90,wpm+boost):wpm);if(ch===' '){t+=dot*4;continue}const code=MORSE[ch];if(!code)continue;for(const sym of code){const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=pitch;o.type='sine';let vol=opt.vol||.7;if(qsbStrength>0&&!opt.local){const wave=(1+Math.sin(qsbPhase+(t-start)*Math.PI*2/qsbPeriod))/2;vol*=qsbFloor+(1-qsbFloor)*wave}g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(vol,t+.006);const len=dot*(sym==='-'?3:1);g.gain.setValueAtTime(vol,t+len-.006);g.gain.linearRampToValueAtTime(0,t+len);o.connect(g).connect(master);o.start(t);o.stop(t+len+.02);if(!opt.local){remoteOscillators.add(o);o.onended=()=>remoteOscillators.delete(o)}t+=len+dot}t+=dot*2}return Math.ceil((t-start)*1000+120)}
function silenceCallers(){receiveEpoch++;for(const o of remoteOscillators){try{o.stop()}catch{}}remoteOscillators.clear()}
function txLocked(){return Date.now()<txBusyUntil}
function transmit(text,wpm=cfg().cqWpm,opt={}){if(txLocked()){setHint('Transmission busy. Wait until the current message has finished.');return 0}silenceCallers();const duration=play(text,wpm,{...opt,local:true});txBusyUntil=Date.now()+duration;if(writer&&$('wkEnabled').checked&&$('wkTx').checked)serialSend(text+' ');return duration}
