function responseDelay(){const c=cfg(),a=Math.max(0,Math.min(5000,Number(c.responseMin)||0)),b=Math.max(0,Math.min(5000,Number(c.responseMax)||0)),min=Math.min(a,b),max=Math.max(a,b);return Math.round(min+Math.random()*(max-min))}
function qrn(){if(!active)return;setTimeout(()=>{if(!active)return;emitQrn();qrn()},1600+Math.random()*2400)}
function levenshtein(a,b){const m=Array.from({length:a.length+1},(_,i)=>[i]);for(let j=1;j<=b.length;j++)m[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)m[i][j]=Math.min(m[i-1][j]+1,m[i][j-1]+1,m[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return m[a.length][b.length]}
function normalizeCallFragment(value){return String(value||'').toUpperCase().replace(/[^A-Z0-9/]/g,'').trim()}
function matchingCurrent(query){query=normalizeCallFragment(query);if(query.length<2)return [];const exactFragment=current.filter(x=>normalizeCallFragment(x.call).includes(query));if(exactFragment.length)return exactFragment;return current.filter(x=>{for(let i=0;i<=Math.max(0,x.call.length-query.length);i++){const fragment=x.call.slice(i,i+query.length);if(levenshtein(query,fragment)<=1)return true}return levenshtein(query,x.call)<=2})}
function repeatMatching(){if(!active||!current.length){setHint('No active callers to repeat.');return}const q=$('callEntry').value.toUpperCase().trim();if(txLocked()){setHint('Transmission busy. Wait for the current message.');return}const matches=matchingCurrent(q),duration=transmit('?',cfg().cqWpm,{pitch:cfg().tone,vol:.72});if(!duration)return;if(q.length<2){setHint('Question mark sent. Enter at least 2 callsign characters for a targeted repeat.');return}if(!matches.length){setHint(`Question mark sent, but no active caller matches ${q}.`);return}setHint(`${matches.length} matching station(s) will repeat after the question mark.`);matches.forEach((x,i)=>scheduleRemote(()=>play(x.call,x.wpm,{pitch:x.pitch,vol:.62/Math.sqrt(matches.length),local:false}),duration+responseDelay()+i*180));noteMiss(matches)}
