function playCallerExchange(dokOnly=false){if(!selectedStation){setHint('No station has been selected yet.');return}const station=selectedStation,query=dokOnly?(station.stationType==='DX'?'NR?':'DOK?'):'AGN',duration=transmit(query,cfg().cqWpm,{pitch:cfg().tone,vol:.72});if(!duration)return;setHint(`Sending ${query}. The station answers only after your transmission.`);setTimeout(()=>{if(!active||selectedStation!==station)return;play(dokOnly?(exchangeForAir(station)):`5NN ${exchangeForAir(station)}`,station.wpm,{pitch:station.pitch,vol:.72,local:false})},duration+responseDelay())}
function repeatAllCalls(){if(!current.length){setHint('No active callers to repeat.');return}const snapshot=current.slice(),duration=transmit('AGN',cfg().cqWpm,{pitch:cfg().tone,vol:.72});if(!duration)return;setHint('Sending AGN. Callers answer only after your transmission.');setTimeout(()=>{if(!active)return;snapshot.forEach((x,i)=>setTimeout(()=>play(x.call,x.wpm,{pitch:x.pitch,vol:.62/Math.sqrt(snapshot.length),local:false}),i*220));noteMiss(snapshot)},duration+responseDelay())}
function updateEsmStatus(){if(!$('debugMode')?.checked)return;setHint($('esm')?.checked?'ESM enabled: Enter selects the next message according to the QSO state.':'ESM disabled: use F1/F2/F3 manually; Enter only attempts to log a completed QSO.')}
function updateEsmHighlight(){document.querySelectorAll('[data-f]').forEach(b=>b.classList.remove('nextAction'));if(!$('esm')?.checked)return;let f=qsoPhase==='calling'&&$('callEntry').value.trim()?2:qsoPhase==='callerExchange'&&$('dokEntry').value.trim()?3:(!active||qsoPhase==='idle'||qsoPhase==='complete'||qsoPhase==='cq')?1:0;if(f)document.querySelector(`[data-f="${f}"]`)?.classList.add('nextAction')}
function handleEsmEnter(){if(blockWhileTimeUp())return;if(!$('esm').checked){logQso();return}if(!active){start();return}if(qsoPhase==='calling'){if($('callEntry').value.trim())sendMessage(2);else sendMessage(1);return}if(qsoPhase==='callerExchange'){if($('dokEntry').value.trim())logQso();else sendMessage(9);return}if(qsoPhase==='idle'||qsoPhase==='complete'||qsoPhase==='cq'){sendMessage(1);return}}
function scheduleCallerResponse(kind,duration){const token=++cqGeneration,delay=Math.max(0,Number(duration)||0)+responseDelay();window.setTimeout(()=>{if(!active||token!==cqGeneration)return;if(kind==='full')spawn();else playCurrentCallers()},delay)}
function sendMessage(f){if(f!==12&&txLocked()){setHint('Transmission busy. Only one own message can be sent at a time.');return}if(f===1)autoHideForCq();let c=cfg(),ce=$('callEntry').value.toUpperCase();if(f===12){$('callEntry').value='';$('dokEntry').value='';updateEsmHighlight();return}if(f===7){repeatMatching();return}if(f===2){sendOurExchange();setTimeout(updateEsmHighlight,50);return}if(f===8){if(qsoPhase==='callerExchange')playCallerExchange(false);else repeatAllCalls();return}if(f===9){playCallerExchange(true);return}if(f===5){sendHisCall();return}let msg={1:`CQ ${contestMode==='cwa'?'CWA':'WAG'} ${c.myCall} TEST`,3:`TU ${c.myCall} TEST`,4:c.myCall,6:'QRL?',10:'QRZ?',11:'NIL'}[f];if(msg){const duration=transmit(msg,c.cqWpm,{pitch:c.tone,vol:.72});if(!duration)return;if(writer&&$('wkEnabled').checked&&$('wkTx').checked)$('serialStatus').textContent=`Connected · F${f} sent`;if(f===1||f===3){selectedStation=null;qsoPhase='cq';if(f===1){current=[];updateCallerInfo();setHint('Full CQ running. A new pileup is being built.');scheduleCallerResponse('full',duration)}else{setHint('TU and short test call running. Remaining stations may answer.');scheduleCallerResponse('remaining',duration)}}setTimeout(updateEsmHighlight,50)}}
async function serialSend(s){if(writer)try{await writer.write(new TextEncoder().encode(s))}catch(e){$('serialStatus').textContent='Error: '+e.message}}
function logQso(){if(!active||!selectedStation||qsoPhase!=='callerExchange'){setHint('Complete the QSO exchange before logging.');setFeedback('partial','QSO is not complete yet.');return}attempts++;let call=$('callEntry').value.toUpperCase().trim(),dok=$('dokEntry').value.toUpperCase().trim(),target=selectedStation,callOk=call===target.call,dokOk=dok===target.dok,ok=callOk&&dokOk;if(ok){correct++;mults.add(dok)}let entry={time:new Date().toISOString(),band:cfg().band,call,dok,rstSent:'599',rstRecv:'599',wpm:target.wpm,stationType:target.stationType,points:ok?(target.stationType==='DX'?3:1):0,status:ok?'OK':`Expected: ${target.call} 599 ${target.dok}`};logs.push(entry);renderLog();if(ok){setFeedback('success','✓ Correct QSO: CALL and DOK were copied correctly.');setHint('QSO logged successfully. Stand by for the next callers.')}else{const parts=[];if(!callOk)parts.push(`CALL should be ${target.call}`);if(!dokOk)parts.push(`Exchange should be ${target.dok}`);setFeedback('error','✗ Incorrect QSO: '+parts.join(' · '));setHint('QSO logged with an error. Review the result above.')}qsoPhase='complete';decayPileup(target);sendMessage(3);$('callEntry').value='';$('dokEntry').value='';$('callEntry').focus();setActiveField('callEntry');selectedStation=null;updateEsmHighlight()}
function renderLog(){let b=$('logBody');b.innerHTML=logs.slice().reverse().map(x=>`<tr><td>${new Date(x.time).toLocaleTimeString()}</td><td>${x.band}</td><td>${x.call}</td><td>${x.rstSent}</td><td>${x.rstRecv}</td><td>${x.dok}</td><td>${x.wpm}</td><td>${x.points}</td><td class="${x.status==='OK'?'ok':'bad'}">${x.status}</td></tr>`).join('');$('qsoCount').textContent=correct;$('accuracy').textContent=(attempts?Math.round(correct/attempts*100):100)+'%';$('multis').textContent=mults.size;let mins=Math.max(1,(Date.now()-(endAt-cfg().duration*60000))/60000);$('rate').textContent=Math.round(correct/mins*60)}
function panelKey(panel){return panel?.dataset.panelKey||''}
function setPanelCollapsed(panel,collapsed){panel.classList.toggle('collapsed',collapsed);const h=panel.querySelector(':scope>h2');if(h)h.setAttribute('aria-expanded',String(!collapsed));localStorage.setItem('wagPanel_'+panelKey(panel),collapsed?'1':'0')}
function savePanelOrder(){localStorage.setItem('wagPanelOrder',JSON.stringify([...document.querySelectorAll('main>section[data-panel-key]')].map(panelKey)))}
function restorePanelOrder(){const main=document.querySelector('main'),defaults=['operating','log','setup','noise','settings','archive','stats'];let order=defaults;try{const saved=JSON.parse(localStorage.getItem('wagPanelOrder')||'[]');if(Array.isArray(saved)&&saved.length)order=[...saved,...defaults.filter(x=>!saved.includes(x))]}catch{}const map=new Map([...main.querySelectorAll(':scope>section[data-panel-key]')].map(p=>[panelKey(p),p]));order.forEach(k=>map.get(k)&&main.append(map.get(k)))}
function initPanelSorting(){const main=document.querySelector('main');let dragged=null,pointerPanel=null,moved=false;for(const panel of main.querySelectorAll(':scope>section[data-panel-key]')){const grip=panel.querySelector(':scope>h2>.dragGrip');grip.addEventListener('mousedown',()=>panel.draggable=true);grip.addEventListener('mouseup',()=>panel.draggable=false);panel.addEventListener('dragstart',e=>{dragged=panel;panel.classList.add('dragging');e.dataTransfer.effectAllowed='move'});panel.addEventListener('dragend',()=>{panel.classList.remove('dragging');panel.draggable=false;dragged=null;savePanelOrder()});panel.addEventListener('dragover',e=>{if(!dragged||dragged===panel)return;e.preventDefault();const r=panel.getBoundingClientRect();main.insertBefore(dragged,e.clientY<r.top+r.height/2?panel:panel.nextSibling)});grip.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')return;pointerPanel=panel;moved=false;grip.setPointerCapture(e.pointerId);panel.classList.add('dragging');e.preventDefault()});grip.addEventListener('pointermove',e=>{if(!pointerPanel)return;moved=true;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('main>section[data-panel-key]');if(target&&target!==pointerPanel){const r=target.getBoundingClientRect();main.insertBefore(pointerPanel,e.clientY<r.top+r.height/2?target:target.nextSibling)}});const finish=e=>{if(!pointerPanel)return;pointerPanel.classList.remove('dragging');pointerPanel=null;savePanelOrder();e.preventDefault()};grip.addEventListener('pointerup',finish);grip.addEventListener('pointercancel',finish);grip.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const sibling=e.key==='ArrowUp'?panel.previousElementSibling:panel.nextElementSibling;if(!sibling)return;if(e.key==='ArrowUp')main.insertBefore(panel,sibling);else main.insertBefore(sibling,panel);savePanelOrder();grip.focus()})}}
function initLayoutControls(){restorePanelOrder();document.querySelectorAll('[data-collapsible=true]').forEach(panel=>{const key=panelKey(panel),saved=localStorage.getItem('wagPanel_'+key),defaultClosed=['settings','setup','noise'].includes(key);setPanelCollapsed(panel,saved===null?defaultClosed:saved==='1');const heading=panel.querySelector(':scope>h2');heading.onclick=e=>{if(e.target.closest('.dragGrip'))return;setPanelCollapsed(panel,!panel.classList.contains('collapsed'))};heading.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('.dragGrip')){e.preventDefault();setPanelCollapsed(panel,!panel.classList.contains('collapsed'))}}});initPanelSorting();$('autoHide').checked=localStorage.getItem('wagAutoHide')==='1';$('compactLayout').checked=localStorage.getItem('wagCompactLayout')==='1';$('colorScheme').value=localStorage.getItem('wagColorScheme')||'system';applyCompactLayout();applyColorScheme();$('autoHide').onchange=()=>localStorage.setItem('wagAutoHide',$('autoHide').checked?'1':'0');$('compactLayout').onchange=()=>{localStorage.setItem('wagCompactLayout',$('compactLayout').checked?'1':'0');applyCompactLayout()};$('colorScheme').onchange=()=>{localStorage.setItem('wagColorScheme',$('colorScheme').value);applyColorScheme()};if(window.matchMedia){const mq=window.matchMedia('(prefers-color-scheme: dark)');mq.addEventListener?.('change',()=>{if($('colorScheme').value==='system')applyColorScheme()})}}
function applyColorScheme(){const selected=$('colorScheme')?.value||'system',resolved=selected==='system'?(window.matchMedia?.('(prefers-color-scheme: light)').matches?'white':'dark'):selected;document.body.classList.remove('theme-dark','theme-gray','theme-matrix','theme-white','theme-forest');document.body.classList.add('theme-'+resolved);document.documentElement.style.colorScheme=resolved==='white'?'light':'dark'}
function applyCompactLayout(){const compact=$('compactLayout').checked;document.body.classList.toggle('compact-layout',compact);document.querySelectorAll('[data-full-label][data-compact-label]').forEach(el=>{const full=el.dataset.fullLabel,short=el.dataset.compactLabel;for(const n of el.childNodes)if(n.nodeType===3&&n.textContent.trim()===(compact?full:short)){n.textContent=n.textContent.replace(compact?full:short,compact?short:full);break}})}
function autoHideForCq(){if(!$('autoHide').checked)return;document.querySelectorAll('.panel.setup,.panel.noise').forEach(p=>setPanelCollapsed(p,true))}
function openChangelog(){$('changelogDialog').showModal()}
function dismissTimeUp(){if(!timeUpLocked)return;timeUpLocked=false;$('timeUpBanner').hidden=true;$('timeUpBanner').textContent='TIME IS UP · TRAINING FINISHED · CLICK TO CLOSE';document.querySelector('.meter').classList.remove('timeExpired');$('status').classList.remove('timeExpired');$('status').textContent='Ready';setHint('Time-up notice dismissed. Start Contest or press Enter to begin a new session.');$('start').disabled=false;$('callEntry').focus()}
function blockWhileTimeUp(){if(!timeUpLocked)return false;setHint('Training has ended. Click the TIME IS UP notice before starting a new session.');$('timeUpBanner').focus();return true}
function tick(){let s=Math.max(0,Math.ceil((endAt-Date.now())/1000));$('clock').textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;if(!s)stop('timeup')}
function start(){if(blockWhileTimeUp())return;txBusyUntil=0;silenceCallers();let c=cfg();if(c.responseMin>c.responseMax){const low=c.responseMax,high=c.responseMin;$('responseMin').value=low;$('responseMax').value=high;c=cfg()}$('timeUpBanner').hidden=true;document.querySelector('.meter').classList.remove('timeExpired');$('status').classList.remove('timeExpired');if(c.minWpm>c.maxWpm){alert('CW Speed min darf nicht größer als max sein.');return}initAudio();active=true;sessionStartedAt=Date.now();sessionSettings={...c};logs=[];attempts=correct=0;mults.clear();current=[];updateCallerInfo();endAt=Date.now()+c.duration*60000;$('start').disabled=true;$('stop').disabled=false;$('status').textContent='Contest running';updateBandAudio();timer=setInterval(tick,250);qrn();renderLog();sendMessage(1);localStorage.setItem('wagcfg',JSON.stringify(c))}
function calculateBattleScore(){const c=sessionSettings||cfg(),minutes=Math.max(.25,((Date.now()-(sessionStartedAt||Date.now()))/60000)),accuracy=attempts?correct/attempts:0,valid=logs.filter(x=>x.status==='OK'),avgWpm=valid.length?valid.reduce((s,x)=>s+(+x.wpm||0),0)/valid.length:(c.minWpm+c.maxWpm)/2,conditions=(c.noise+c.qrn+c.qsb+c.qrm)/400,speedFactor=.65+avgWpm/40,pileupFactor=1+Math.max(0,c.pileup-1)*.1,conditionFactor=1+conditions*.75,responseAvg=(c.responseMin+c.responseMax)/2,responseFactor=1+Math.max(0,1500-responseAvg)/3000,dxFactor=1+(c.dxRatio/100)*.15,enduranceFactor=1+Math.min(.5,minutes/120),accuracyFactor=Math.pow(accuracy,1.5),difficulty=speedFactor*pileupFactor*conditionFactor*responseFactor*dxFactor,endurance=enduranceFactor;return {score:Math.round(correct*100*accuracyFactor*difficulty*endurance),minutes:+minutes.toFixed(2),accuracy:Math.round(accuracy*100),avgWpm:+avgWpm.toFixed(1),pileup:Math.max(1,Math.min(10,Number.parseInt(c.pileup,10)||1)),difficulty:+difficulty.toFixed(2),style:contestMode.toUpperCase(),noise:c.noise,qsb:c.qsb,qrn:c.qrn,qrm:c.qrm,responseMin:c.responseMin,responseMax:c.responseMax,dxShare:c.dxRatio}}
function stop(reason='manual'){if(!active)return;txBusyUntil=0;silenceCallers();active=false;clearInterval(timer);cqGeneration++;if(ac&&noiseNode?.g){const now=ac.currentTime,currentGain=noiseNode.g.gain.value;noiseNode.g.gain.cancelScheduledValues(now);noiseNode.g.gain.setValueAtTime(currentGain,now);noiseNode.g.gain.linearRampToValueAtTime(0,now+1.5)}$('start').disabled=false;$('stop').disabled=true;if(reason==='timeup'){timeUpLocked=true;$('timeUpBanner').hidden=false;document.querySelector('.meter').classList.add('timeExpired');$('status').classList.add('timeExpired');$('status').textContent='TIME IS UP';$('start').disabled=true;setFeedback('neutral','Training time has ended. Click the TIME IS UP notice to unlock a new session.')}else{timeUpLocked=false;$('timeUpBanner').hidden=true;$('status').textContent='Stopped'}const battle=calculateBattleScore();lastSession={callsign:cfg().myCall,score:battle.score,qsos:correct,accuracy:battle.accuracy,multipliers:mults.size,duration:battle.minutes,version:APP_VERSION,style:battle.style,avgWpm:battle.avgWpm,pileup:battle.pileup,difficulty:battle.difficulty,noise:battle.noise,qsb:battle.qsb,qrn:battle.qrn,qrm:battle.qrm,responseMin:battle.responseMin,responseMax:battle.responseMax,dxShare:battle.dxShare};$('submitScore').disabled=!correct;$('summary').innerHTML=`<strong><span class="uiEmoji">🏆</span> Battle Score ${battle.score.toLocaleString()}</strong> · ${correct} valid QSOs out of ${attempts} attempts · ${mults.size} multipliers · ${battle.avgWpm} avg WPM · difficulty ${battle.difficulty}×<br><span class="uiEmoji">🎯</span> Accuracy ${battle.accuracy}% · <span class="uiEmoji">🚀</span> average rate ${$('rate').textContent}/h · <span class="uiEmoji">⏱️</span> ${battle.minutes} min`;if(reason==='timeup'){$('timeUpBanner').innerHTML='<div class="timeUpTitle"><span class="uiEmoji">⏱️</span> TIME IS UP · TRAINING FINISHED · CLICK OUTSIDE THE BUTTON TO CLOSE</div>'+roundScoreHtml(battle);const submit=$('timeUpSubmitScore');if(submit)submit.addEventListener('click',async e=>{e.stopPropagation();const state=$('timeUpSubmitStatus');submit.disabled=true;if(state)state.textContent='Submitting...';try{await submitLeaderboard(true);if(state)state.textContent='Submitted successfully'}catch(err){if(state)state.textContent='Submission failed';submit.disabled=false}})}qsoPhase='idle';current=[];updateCallerInfo();updateEsmHighlight();if(reason==='timeup')setHint(`🏆 Finished: Battle Score ${battle.score.toLocaleString()} · ${correct} QSOs · ${battle.accuracy}% accuracy · ${battle.avgWpm} avg WPM · difficulty ${battle.difficulty}×`)}
async function disconnectSerial(){try{if(writer){writer.releaseLock();writer=null}if(serialPort){await serialPort.close();serialPort=null}}catch(e){}$('serialStatus').textContent='Not connected';$('serial').disabled=!$('wkEnabled').checked;$('serialDisconnect').disabled=true}
async function connectSerial(){if(!$('wkEnabled').checked)return;if(!('serial'in navigator)){alert('Web Serial is not supported in this browser. Use Edge or Chrome over HTTPS or localhost.');return}try{serialPort=await navigator.serial.requestPort();await serialPort.open({baudRate:+$('baud').value});writer=serialPort.writable.getWriter();$('serialStatus').textContent='Verbunden';readSerial()}catch(e){$('serialStatus').textContent='Not connected: '+e.message}}
async function readSerial(){let field='call';while(serialPort?.readable){const reader=serialPort.readable.getReader();try{while(true){let {value,done}=await reader.read();if(done)break;if($('wkMode').checked&&value){let raw=new TextDecoder().decode(value).toUpperCase();for(const ch of raw){if(ch===' '||ch==='\t'){field='dok';$('dokEntry').focus()}else if(ch==='\r'||ch==='\n'){if($('callEntry').value||$('dokEntry').value)logQso();field='call'}else if(ch==='\b'||ch.charCodeAt(0)===127){let e=field==='call'?$('callEntry'):$('dokEntry');e.value=e.value.slice(0,-1)}else if(/[A-Z0-9/]/.test(ch)){let e=field==='call'?$('callEntry'):$('dokEntry');e.value+=ch}}}}}finally{reader.releaseLock()}}}
function exportLog(){let head='START-OF-LOG: 3.0\nCONTEST: WAG\nCALLSIGN: '+cfg().myCall+'\nCATEGORY-MODE: CW\n',q=logs.filter(x=>x.status==='OK').map(x=>{let d=new Date(x.time),ds=d.toISOString().slice(0,10).replaceAll('-',''),tm=d.toISOString().slice(11,16).replace(':','');return `QSO:  7000 CW ${ds} ${tm} ${cfg().myCall.padEnd(13)} 599 ${cfg().myDok.padEnd(6)} ${x.call.padEnd(13)} 599 ${x.dok}`}).join('\n');let csv='time,band,call,dok,wpm,points,status\n'+logs.map(x=>Object.values(x).join(',')).join('\n'),blob=new Blob([head+q+'\nEND-OF-LOG:\n\n--- CSV ---\n'+csv],{type:'text/plain'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='wag-training-log.txt';a.click();URL.revokeObjectURL(a.href)}
function setActiveField(id){['callEntry','dokEntry'].forEach(x=>$(x).classList.toggle('fieldActive',x===id))}
function openPrivacy(){renderPrivacyContent();if($('privacyDialog')&&!$('privacyDialog').open)$('privacyDialog').showModal()}
function deleteLocalAppData(){if(!confirm('Delete all local trainer settings, imported calls, layout and acknowledgements on this device? Server leaderboard entries are not deleted.'))return;for(const key of Object.keys(localStorage))if(key.startsWith('wag'))localStorage.removeItem(key);location.reload()}
function acknowledgeStorageNotice(){localStorage.setItem('wagStorageNotice','1');$('storageNotice').classList.add('hidden')}
function roundScoreHtml(battle){return `<div class="roundScore"><div><span class="uiEmoji">🏆</span> <strong>${battle.score.toLocaleString()}</strong><span>Battle Score</span></div><div><span class="uiEmoji">✅</span> <strong>${correct}</strong><span>QSOs</span></div><div><span class="uiEmoji">🎯</span> <strong>${battle.accuracy}%</strong><span>Accuracy</span></div><div><span class="uiEmoji">⚡</span> <strong>${battle.avgWpm}</strong><span>Avg WPM</span></div><div><span class="uiEmoji">🔥</span> <strong>${battle.difficulty}×</strong><span>Difficulty</span></div><div><span class="uiEmoji">🚀</span> <strong>${$('rate').textContent}/h</strong><span>Rate</span></div></div><div class="timeUpActions"><button id="timeUpSubmitScore" class="primary" type="button" ${correct?'':'disabled'}>🏆 Submit to Leaderboard</button><span id="timeUpSubmitStatus">${correct?'Ready to submit':'No valid QSO to submit'}</span></div>`}
function getLeaderboardDeleteToken(){let token=localStorage.getItem('wagLeaderboardDeleteToken');if(!token){const bytes=new Uint8Array(32);crypto.getRandomValues(bytes);token=[...bytes].map(x=>x.toString(16).padStart(2,'0')).join('');localStorage.setItem('wagLeaderboardDeleteToken',token)}return token}
async function deleteMyLeaderboardCall(){const callsign=$('myCall').value.toUpperCase().trim();if(!/^[A-Z0-9\/]{3,15}$/.test(callsign)){alert('Enter a valid callsign under Station & Session first.');return}if(!confirm(`Delete leaderboard results for ${callsign} that were submitted from this browser?`))return;const button=$('deleteLeaderboardCallBtn');button.disabled=true;try{const data=await leaderboardRequest('delete',{callsign,deleteToken:getLeaderboardDeleteToken()});alert(data.deleted?`${data.deleted} leaderboard result(s) deleted for ${callsign}.`:`No deletable result for ${callsign} was found. Only results submitted from this browser after v3.2.2 can be deleted.`);await loadLeaderboard()}catch(e){alert('Leaderboard deletion failed: '+e.message)}finally{button.disabled=false}}
async function leaderboardRequest(action,payload=null,query={}){const params=new URLSearchParams({action,...query}),options=payload?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}:{};const r=await fetch(`api/leaderboard.php?${params}`,options),data=await r.json();if(!r.ok||!data.ok)throw new Error(data.error||`HTTP ${r.status}`);return data}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let leaderboardLimit=10,leaderboardCall='';
function leaderboardNumber(value,digits=0){const n=Number(value);return Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:digits}):'0'}
function leaderboardRowsHtml(rows){return rows.map(x=>`<tr><td>${x.overall_rank<=50?x.overall_rank:'–'}</td><td><button class="leaderboardCallLink" type="button" data-call="${escapeHtml(x.callsign)}">${escapeHtml(x.callsign)}</button>${x.call_rank<=10?`<span class="callRankBadge">Call #${x.call_rank}</span>`:''}</td><td><strong>${leaderboardNumber(x.score)}</strong></td><td>${escapeHtml(x.style||'WAG')}</td><td>${x.qsos}</td><td>${x.accuracy}%</td><td>${leaderboardNumber(x.avg_wpm,1)}</td><td>${x.pileup}</td><td>${leaderboardNumber(x.duration,2)}</td><td>${leaderboardNumber(x.difficulty,2)}×</td><td>${x.multipliers}</td><td>${escapeHtml(x.created_at||'')}</td></tr>`).join('')}
function bindLeaderboardCalls(){document.querySelectorAll('.leaderboardCallLink').forEach(button=>button.onclick=()=>loadCallSubmissions(button.dataset.call))}
async function loadLeaderboard(limit=leaderboardLimit){leaderboardLimit=Math.max(10,Math.min(100,Number.parseInt(limit,10)||10));leaderboardCall='';const body=$('leaderboardBody');body.innerHTML='<tr><td colspan="12">Loading...</td></tr>';try{const data=await leaderboardRequest('list',null,{limit:leaderboardLimit});body.innerHTML=data.rows.length?leaderboardRowsHtml(data.rows):'<tr><td colspan="12">No submitted results yet.</td></tr>';bindLeaderboardCalls();$('leaderboardStatus').textContent=`Showing ${data.rows.length} individual submissions. Overall TOP 50 and per-call TOP 10 ranks are maintained.`;$('leaderboardBackBtn').hidden=true;$('leaderboardLimit').disabled=false;$('leaderboardTitle').textContent='Server Leaderboard'}catch(e){body.innerHTML='<tr><td colspan="12">Leaderboard unavailable. Check PHP and SQLite.</td></tr>';$('leaderboardStatus').textContent=e.message}}
async function loadCallSubmissions(callsign){leaderboardCall=callsign;const body=$('leaderboardBody');body.innerHTML='<tr><td colspan="12">Loading...</td></tr>';try{const data=await leaderboardRequest('call',null,{callsign});body.innerHTML=data.rows.length?leaderboardRowsHtml(data.rows):'<tr><td colspan="12">No submissions found.</td></tr>';bindLeaderboardCalls();$('leaderboardTitle').textContent=`All submissions · ${callsign}`;$('leaderboardStatus').textContent=`${data.rows.length} submission(s) for ${callsign}. The best 10 carry a per-call rank.`;$('leaderboardBackBtn').hidden=false;$('leaderboardLimit').disabled=true}catch(e){body.innerHTML='<tr><td colspan="12">Could not load submissions.</td></tr>';$('leaderboardStatus').textContent=e.message}}
async function submitLeaderboard(rethrow=false){if(!lastSession)return;$('submitScore').disabled=true;$('leaderboardStatus').textContent='Submitting...';try{await leaderboardRequest('submit',{...lastSession,deleteToken:getLeaderboardDeleteToken()});$('leaderboardStatus').textContent='Result submitted successfully.';await loadLeaderboard();$('leaderboardDialog').showModal()}catch(e){$('leaderboardStatus').textContent='Submission failed: '+e.message;if(rethrow)throw e}finally{$('submitScore').disabled=false}}
