const originalNodes=new WeakMap();function setLanguage(lang){if(!['en','de','fr','es'].includes(lang))lang='en';document.documentElement.lang=lang;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(!n.nodeValue.trim())continue;if(!originalNodes.has(n))originalNodes.set(n,n.nodeValue.trim());const orig=originalNodes.get(n),translated=I18N[lang]?.[orig]||orig;n.nodeValue=n.nodeValue.replace(n.nodeValue.trim(),translated)}localStorage.setItem('wagLanguage',lang);$('language').value=lang;document.title=APP_NAME;renderHelpContent(lang);renderPrivacyContent(lang)}
$('privacyBtn')?.addEventListener('click',openPrivacy);$('storagePrivacyBtn')?.addEventListener('click',openPrivacy);$('storageNoticeOk')?.addEventListener('click',acknowledgeStorageNotice);$('storageNoticeClose')?.addEventListener('click',acknowledgeStorageNotice);$('deleteLocalDataBtn')?.addEventListener('click',deleteLocalAppData);$('deleteLeaderboardCallBtn')?.addEventListener('click',deleteMyLeaderboardCall);if(localStorage.getItem('wagStorageNotice')==='1')$('storageNotice')?.classList.add('hidden');$('leaderboardBtn').onclick=()=>{$('leaderboardDialog').showModal();loadLeaderboard()};$('refreshLeaderboard').onclick=()=>leaderboardCall?loadCallSubmissions(leaderboardCall):loadLeaderboard();$('leaderboardLimit').onchange=e=>loadLeaderboard(e.target.value);$('leaderboardBackBtn').onclick=()=>loadLeaderboard(leaderboardLimit);$('submitScore').onclick=submitLeaderboard;const savedDxRatio=localStorage.getItem('wagDxRatio');if(savedDxRatio)$('dxRatio').value=savedDxRatio;$('dxRatio').onchange=()=>localStorage.setItem('wagDxRatio',$('dxRatio').value);$('germanOnly').checked=localStorage.getItem('wagGermanOnly')==='1';$('dxOnly').checked=localStorage.getItem('wagDxOnly')==='1';function syncCallerFilters(source){if(source==='de'&&$('germanOnly').checked)$('dxOnly').checked=false;if(source==='dx'&&$('dxOnly').checked){$('germanOnly').checked=false;$('f74Mode').checked=false}localStorage.setItem('wagGermanOnly',$('germanOnly').checked?'1':'0');localStorage.setItem('wagDxOnly',$('dxOnly').checked?'1':'0')}$('germanOnly').onchange=()=>syncCallerFilters('de');$('dxOnly').onchange=()=>syncCallerFilters('dx');$('f74Mode').checked=localStorage.getItem('wagF74Mode')==='1';$('f74Mode').onchange=()=>{if($('f74Mode').checked){$('dxOnly').checked=false;localStorage.setItem('wagDxOnly','0')}localStorage.setItem('wagF74Mode',$('f74Mode').checked?'1':'0')};if(localStorage.getItem('wagEsm')!==null)$('esm').checked=localStorage.getItem('wagEsm')==='1';const savedDebug=localStorage.getItem('wagDebug');$('debugMode').checked=savedDebug===null?true:savedDebug==='1';$('debugMode').onchange=updateDebugMode;updateDebugMode();initLayoutControls();$('helpBtn').onclick=()=>{renderHelpContent();$('helpDialog').showModal()};$('resetDefaultsBtn').onclick=resetToDefaults;document.querySelectorAll('.modeButton').forEach(b=>b.onclick=()=>{if(b.dataset.mode===contestMode)return;if(applyModeDefaults(b.dataset.mode,true)){localStorage.removeItem('wagcfg');setFeedback('neutral',`${b.dataset.mode.toUpperCase()} Style defaults applied.`)}});$('titleVersionBtn').onclick=openChangelog;$('timeUpBanner').onclick=e=>{if(e.target.closest('button,a'))return;dismissTimeUp()};$('timeUpBanner').addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&timeUpLocked){e.preventDefault();dismissTimeUp()}});$('wkEnabled').onchange=async e=>{if(!e.target.checked){await disconnectSerial()}else{$('serial').disabled=false}};$('serialDisconnect').onclick=disconnectSerial;$('winkeyerBtn').onclick=()=>$('winkeyerDialog').showModal();$('language').onchange=e=>setLanguage(e.target.value);$('openArchive').onclick=()=>window.open('https://dxhf2.darc.de/~waglog/arch_res.cgi?form=referat&lang=de','_blank','noopener');$('archiveFile').onchange=e=>e.target.files[0]&&importArchiveFile(e.target.files[0]);$('start').onclick=start;$('stop').onclick=()=>stop('manual');$('logBtn').onclick=logQso;$('repeat').onclick=()=>lastPhrase&&transmit(lastPhrase,cfg().minWpm,{pitch:cfg().tone,vol:.72});$('reveal').onclick=()=>{$('hint').textContent=current.map(x=>x.call+' '+x.dok+' @'+x.wpm+' WPM / '+x.pitch+' Hz').join(' | ')};$('export').onclick=exportLog;$('serial').onclick=connectSerial;document.querySelectorAll('[data-f]').forEach(b=>b.onclick=()=>sendMessage(+b.dataset.f));
$('callEntry').addEventListener('focus',()=>setActiveField('callEntry'));$('dokEntry').addEventListener('focus',()=>setActiveField('dokEntry'));$('callEntry').addEventListener('input',updateEsmHighlight);$('dokEntry').addEventListener('input',updateEsmHighlight);$('esm').addEventListener('change',()=>{updateEsmHighlight();updateEsmStatus();localStorage.setItem('wagEsm',$('esm').checked?'1':'0')});$('callEntry').addEventListener('keydown',e=>{if(e.key===' '){e.preventDefault();$('dokEntry').focus()}else if(e.key==='Enter'){e.preventDefault();handleEsmEnter()}});$('dokEntry').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();handleEsmEnter()}});window.addEventListener('keydown',e=>{if(timeUpLocked){if(e.key==='Enter'){e.preventDefault();blockWhileTimeUp()}return}if(/^F([1-9]|1[0-2])$/.test(e.key)){e.preventDefault();sendMessage(+e.key.slice(1))}if(e.key==='Escape'){$('callEntry').value='';$('dokEntry').value='';updateEsmHighlight()}if(e.key==='='&&lastPhrase){e.preventDefault();transmit(lastPhrase,cfg().cqWpm,{pitch:cfg().tone,vol:.72})}});
for(const id of ['noise','qrn','qsbLevel','qrmLevel']){$(id).oninput=()=>{$(id+'Out').textContent=$(id).value+'%';if(['noise','qrmLevel'].includes(id))updateBandAudio()}}
try{if(localStorage.getItem('wagVersion')!=='3.6.0'){localStorage.setItem('wagVersion','3.6.0')}let c=JSON.parse(localStorage.getItem('wagcfg'));if(c)for(const [k,v]of Object.entries(c)){let e=$(k);if(e)e.type==='checkbox'?e.checked=v:e.value=v}}catch{};
try{const imported=JSON.parse(localStorage.getItem('wagImportedCalls')||'[]');const m=new Map(callPool.map(x=>[x[0],x[1]]));for(const x of imported)if(Array.isArray(x)&&x.length>1)m.set(x[0],x[1]);callPool=[...m.entries()].map(x=>[x[0],x[1],'DE'])}catch{}try{const importedDx=JSON.parse(localStorage.getItem('wagImportedDxCalls')||'[]'),dx=new Set(foreignPool.map(x=>x[0]));for(const call of importedDx)if(typeof call==='string'&&looksLikeCall(call)&&!isGermanCall(call))dx.add(call);foreignPool=[...dx].map(call=>[call,'','DX'])}catch{}detectBrowser();setLanguage(localStorage.getItem('wagLanguage')||navigator.language.slice(0,2));document.querySelectorAll('.modeButton').forEach(b=>b.classList.toggle('active',b.dataset.mode===contestMode));updateCallCount();updateCallerInfo();updateEsmHighlight();setActiveField('callEntry');if(localStorage.getItem('wagHelpShown')!=='1'){renderHelpContent();setTimeout(()=>{$('helpDialog').showModal();localStorage.setItem('wagHelpShown','1')},150)} 
